package dev.mcpmcp.core;
import com.google.gson.*;import java.util.*;import java.util.regex.Pattern;
/** Pure declaration checks: never loads or constructs a packet. */
public final class PluginValidation {
 private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
 private static void closed(JsonObject o,String... keys){Set<String> allowed=Set.of(keys);for(String k:o.keySet())need(allowed.contains(k),"unknown_declaration_"+k);}
 private static String text(JsonObject o,String k){String s=Jsons.str(o,k,"");need(!s.isEmpty(),"missing_"+k);return s;}
 public static void manifest(JsonObject m){Schema.bounded(m);closed(m,"api","id","mod_id","minecraft","loader","target_sha256","actions");need(Jsons.integer(m,"api",0)==1,"plugin_api_mismatch");need(text(m,"id").matches("[a-z0-9_.-]{1,96}"),"invalid_plugin_id");need(text(m,"mod_id").matches("[a-z0-9_.-]{1,96}"),"invalid_mod_id");for(String k:List.of("minecraft","loader","target_sha256"))if(m.has(k))text(m,k);if(m.has("target_sha256"))need(text(m,"target_sha256").matches("[a-f0-9]{64}"),"invalid_target_hash");if(m.has("actions"))actions(Jsons.array(m,"actions"));}
 public static void actions(JsonArray a){Schema.bounded(a);need(a.size()<=128,"plugin_action_limit");for(JsonElement e:a){need(e.isJsonObject(),"action_object_required");action(e.getAsJsonObject());}}
 public static void action(JsonObject a){Schema.bounded(a);closed(a,"name","description","permission","transport","input_schema","packet","preconditions","verify");need(text(a,"name").matches("[a-z0-9_.-]{1,128}"),"invalid_action_name");if(a.has("description"))Jsons.str(a,"description","");need(Set.of("normal","hack","cheat").contains(Jsons.str(a,"permission","normal")),"invalid_plugin_permission");need(Jsons.str(a,"transport","packet").equals("packet"),"declarative_actions_require_packet_transport");need(a.has("input_schema")&&a.get("input_schema").isJsonObject(),"missing_input_schema");JsonObject s=a.getAsJsonObject("input_schema");schema(s);need(Jsons.str(s,"type","").equals("object"),"input_schema_object_required");need(a.has("packet")&&a.get("packet").isJsonObject(),"missing_packet_declaration");packet(a.getAsJsonObject("packet"),s);for(String k:List.of("preconditions","verify"))if(a.has(k)){JsonArray cs=Jsons.array(a,k);need(cs.size()<=32&&(!k.equals("verify")||!cs.isEmpty()),"condition_count_limit");for(JsonElement c:cs)condition(c.getAsJsonObject(),s,true);}}
 public static void schema(JsonObject s){Schema.bounded(s);schemaNode(s,0);}
 private static void schemaNode(JsonObject s,int depth){need(depth<=12,"schema_depth");closed(s,"type","properties","required","additionalProperties","items","minItems","maxItems","minLength","maxLength","maxProperties","minimum","maximum","enum","pattern","description");String type=Jsons.str(s,"type","any");need(Set.of("object","array","string","integer","number","boolean","null","any").contains(type),"unsupported_schema_type");for(String k:List.of("minItems","maxItems","minLength","maxLength","maxProperties"))if(s.has(k))need(Jsons.integer(s,k,0)>=0,"invalid_schema_bound");for(String k:List.of("minimum","maximum"))if(s.has(k))Jsons.number(s,k,0);need(Jsons.number(s,"minimum",-1e30)<=Jsons.number(s,"maximum",1e30),"schema_bounds");need(Jsons.integer(s,"minItems",0)<=Jsons.integer(s,"maxItems",128)&&Jsons.integer(s,"minLength",0)<=Jsons.integer(s,"maxLength",8192),"schema_bounds");if(s.has("pattern"))Pattern.compile(Jsons.str(s,"pattern",""));if(s.has("description"))Jsons.str(s,"description","");if(s.has("enum"))need(!Jsons.array(s,"enum").isEmpty(),"empty_enum");JsonObject p=Jsons.object(s,"properties");for(var e:p.entrySet()){need(e.getValue().isJsonObject(),"schema_object_required");schemaNode(e.getValue().getAsJsonObject(),depth+1);}Set<String> required=new HashSet<>();for(JsonElement r:Jsons.array(s,"required")){need(r.isJsonPrimitive()&&r.getAsJsonPrimitive().isString()&&p.has(r.getAsString())&&required.add(r.getAsString()),"invalid_schema_required");}if(s.has("items"))schemaNode(s.getAsJsonObject("items"),depth+1);if(s.has("additionalProperties")){JsonElement v=s.get("additionalProperties");if(v.isJsonObject())schemaNode(v.getAsJsonObject(),depth+1);else need(v.isJsonPrimitive()&&v.getAsJsonPrimitive().isBoolean(),"invalid_additional_properties");}}
 private static void packet(JsonObject p,JsonObject s){closed(p,"packet_class","channel","mode","signature","values","fields");need(text(p,"packet_class").matches("[A-Za-z_$][A-Za-z0-9_$.]{1,255}"),"invalid_packet_class");if(p.has("channel"))text(p,"channel");String mode=Jsons.str(p,"mode","constructor");if(mode.equals("constructor")){need(p.has("signature")&&p.has("values")&&!p.has("fields"),"constructor_shape");JsonArray sig=Jsons.array(p,"signature"),v=Jsons.array(p,"values");need(sig.size()==v.size()&&sig.size()<=16,"constructor_arity");for(JsonElement t:sig)need(t.isJsonPrimitive()&&t.getAsJsonPrimitive().isString()&&t.getAsString().matches("[A-Za-z_$][A-Za-z0-9_$.]{0,255}"),"literal_signature_required");for(int i=0;i<sig.size();i++)value(v.get(i),sig.get(i).getAsString(),s);bindings(v,s);}else if(mode.equals("wire")){need(p.has("fields")&&!p.has("signature")&&!p.has("values"),"wire_shape");JsonArray fs=Jsons.array(p,"fields");need(fs.size()<=128,"wire_field_limit");for(JsonElement e:fs){JsonObject f=e.getAsJsonObject();closed(f,"type","value");need(Set.of("byte","short","int","varint","long","varlong","boolean","float","double","utf","uuid","block_pos","item_stack","nbt").contains(text(f,"type"))&&f.has("value"),"invalid_wire_field");String ft=text(f,"type");String vt=switch(ft){case "varint"->"int";case "varlong"->"long";case "utf"->"java.lang.String";case "uuid"->"java.util.UUID";case "block_pos"->"net.minecraft.core.BlockPos";case "item_stack"->"net.minecraft.world.item.ItemStack";case "nbt"->"net.minecraft.nbt.CompoundTag";default->ft;};value(f.get("value"),vt,s);bindings(f.get("value"),s);}}else need(false,"invalid_packet_mode");}
 public static void value(JsonElement e,String type,JsonObject schema){
 String expected=switch(type){case "int","long","short","byte","java.lang.Integer","java.lang.Long"->"integer";case "float","double"->"number";case "boolean"->"boolean";case "net.minecraft.core.BlockPos","net.minecraft.world.item.ItemStack"->"object";default->"string";};
 if(binding(e,schema)){JsonObject b=e.getAsJsonObject();String actual;if(b.has("param"))actual=Jsons.str(Jsons.object(schema,"properties").getAsJsonObject(text(b,"param")),"type","any");else actual=text(b,"context").equals("player_uuid")?"string":"integer";need(actual.equals(expected)||(expected.equals("number")&&actual.equals("integer")),"binding_type_mismatch");return;}
 need(e!=null&&!e.isJsonNull(),"null_packet_value");switch(expected){case "integer"->{need(e.isJsonPrimitive()&&e.getAsJsonPrimitive().isNumber(),"integer_required");try{long n=e.getAsBigDecimal().longValueExact();long min=Long.MIN_VALUE,max=Long.MAX_VALUE;switch(type){case "int","java.lang.Integer"->{min=Integer.MIN_VALUE;max=Integer.MAX_VALUE;}case "short"->{min=Short.MIN_VALUE;max=Short.MAX_VALUE;}case "byte"->{min=Byte.MIN_VALUE;max=Byte.MAX_VALUE;}}need(n>=min&&n<=max,"integer_out_of_range");}catch(ArithmeticException ex){throw new IllegalArgumentException("integer_out_of_range");}}case "number"->{need(e.isJsonPrimitive()&&e.getAsJsonPrimitive().isNumber()&&Double.isFinite(e.getAsDouble()),"finite_number_required");if(type.equals("float"))need(Float.isFinite(e.getAsFloat()),"float_out_of_range");}case "boolean"->need(e.isJsonPrimitive()&&e.getAsJsonPrimitive().isBoolean(),"boolean_required");case "object"->{need(e.isJsonObject(),"packet_object_required");JsonObject o=e.getAsJsonObject();if(type.equals("net.minecraft.core.BlockPos")){closed(o,"x","y","z");for(String k:List.of("x","y","z")){need(o.has(k),"missing_"+k);value(o.get(k),"int",schema);}}else{closed(o,"item_id","count","nbt");need(o.has("item_id"),"missing_item_id");value(o.get("item_id"),"java.lang.String",schema);if(o.has("count"))value(o.get("count"),"int",schema);if(o.has("nbt"))value(o.get("nbt"),"java.lang.String",schema);}}default->{need(e.isJsonPrimitive()&&e.getAsJsonPrimitive().isString(),"string_packet_value_required");if(type.equals("java.util.UUID"))UUID.fromString(e.getAsString());}}}
 private static boolean binding(JsonElement e,JsonObject s){if(e==null||!e.isJsonObject())return false;JsonObject o=e.getAsJsonObject();if(o.has("param")||o.has("context")){need(o.size()==1,"invalid_binding");if(o.has("param"))need(Jsons.object(s,"properties").has(text(o,"param")),"unknown_parameter_binding");else need(Set.of("menu_id","menu_state_id","player_uuid").contains(text(o,"context")),"unknown_context_key");return true;}return false;}
 private static void bindings(JsonElement e,JsonObject s){if(binding(e,s))return;if(e.isJsonObject())for(var x:e.getAsJsonObject().entrySet())bindings(x.getValue(),s);if(e.isJsonArray())for(JsonElement x:e.getAsJsonArray())bindings(x,s);}
 public static void condition(JsonObject c,JsonObject s,boolean templates){String kind=text(c,"kind");switch(kind){case "position"->{closed(c,"kind","x","y","z","tolerance");for(String k:List.of("x","y","z"))number(c,k,s,templates,-30000000,30000000,true);number(c,"tolerance",s,templates,0,64,false);}case "block"->{closed(c,"kind","x","y","z","block_id");for(String k:List.of("x","y","z"))number(c,k,s,templates,-30000000,30000000,true);identifier(c,"block_id",s,templates);}case "menu"->{closed(c,"kind","class");if(!(templates&&binding(c.get("class"),s)))need(text(c,"class").matches("[A-Za-z_$][A-Za-z0-9_$.]{0,255}"),"invalid_menu_class");}case "inventory"->{closed(c,"kind","item_id","min_count");identifier(c,"item_id",s,templates);number(c,"min_count",s,templates,0,2147483647,false);}default->need(false,"unknown_condition_kind");}}
 private static void identifier(JsonObject c,String k,JsonObject s,boolean t){need(c.has(k),"missing_"+k);if(t&&binding(c.get(k),s)){value(c.get(k),"java.lang.String",s);return;}need(text(c,k).matches("[a-z0-9_.-]+:[a-z0-9_./-]+"),"invalid_condition_id");}
 private static void number(JsonObject c,String k,JsonObject s,boolean t,double min,double max,boolean required){if(!c.has(k)){need(!required,"missing_"+k);return;}if(t&&binding(c.get(k),s)){value(c.get(k),k.equals("tolerance")||Jsons.str(c,"kind","").equals("position")?"double":"int",s);return;}double v=Jsons.number(c,k,0);need(v>=min&&v<=max,"condition_bound");if(!k.equals("tolerance")&&!Jsons.str(c,"kind","").equals("position"))need(v==Math.rint(v),"integer_condition_required");}
 private PluginValidation(){}
}
